/**
 * Pseudonymisieren (lokal) — n8n Code-Node
 *
 * Nimmt strukturierte Formulardaten entgegen, trennt die personenbezogenen
 * Felder ab und ersetzt sie durch eine ID. Ab hier arbeitet die gesamte
 * Pipeline nur noch mit der ID.
 *
 * Warum feldbasiert und nicht per Texterkennung:
 * Der Kunde traegt seine Daten in ein Formular ein (Beschluss 12.07.2026:
 * Excel-/Formular-Eingaben statt OCR). Damit ist bekannt, WELCHES Feld ein
 * Name ist — eine Erkennung per NER ist unnoetig und waere nur eine weitere
 * Fehlerquelle. Freitextfelder werden zusaetzlich nach den bekannten Werten
 * durchsucht, falls der Kunde seinen Namen dort nochmal erwaehnt.
 *
 * Rueckweg: KEINER. Der pseudonymisierte Zustand ist der Endzustand fuer
 * alles, was danach kommt (LLM, Speicherung, BC2/BC3/BC4). Kundennachrichten
 * entstehen spaeter aus Vorlage + Mapping, nicht durch Ruecksetzung im LLM-Pfad.
 * Vgl. BC1-Architektur v6, AP 1.2: "keine personenbezogenen Daten gelangen in
 * nachgelagerte Sub-Komponenten ohne Anonymisierung".
 *
 * Eingabe (json):
 *   formular  : { feldname: wert }                 die Formulardaten
 *   entitaeten: { idTyp, felder[] }[]              welche Felder zu einer Person gehoeren
 *   freitextFelder: string[]                       Felder, die zusaetzlich durchsucht werden
 * Ausgabe (json):
 *   fachdaten : Formular ohne PII, dafuer mit <idTyp>_id
 *   mapping   : { id -> { feld: wert } }           bleibt lokal / geht in den PII-Tresor
 *   piiLog    : Nachweis, was ersetzt wurde (ohne Klartext)
 */

const PRAEFIX = {
  kunde: 'KUN',
  passagier: 'PAX',
  mitarbeiter: 'MIT',
  berater: 'BER',       // UC3 Consultant Placement
  patient: 'PAT',
};

const eingabe = $input.first().json;
const formular = { ...(eingabe.formular ?? {}) };
const entitaeten = eingabe.entitaeten ?? [];
const freitextFelder = eingabe.freitextFelder ?? [];

const mapping = {};
const piiLog = [];
const zaehler = {};
const klartextWerte = [];   // fuer die Freitext-Suche

for (const ent of entitaeten) {
  const praefix = PRAEFIX[ent.idTyp] ?? 'PII';
  zaehler[praefix] = (zaehler[praefix] ?? 0) + 1;
  const id = `${praefix}-${String(zaehler[praefix]).padStart(4, '0')}`;

  // PII-Felder aus den Fachdaten herausloesen und im Mapping ablegen
  const daten = {};
  for (const feld of ent.felder ?? []) {
    const wert = formular[feld];
    if (wert === undefined || wert === null || String(wert).trim() === '') continue;
    daten[feld] = wert;
    klartextWerte.push(String(wert).trim());
    delete formular[feld];
  }
  if (!Object.keys(daten).length) continue;

  mapping[id] = daten;
  formular[`${ent.idTyp}_id`] = id;
  piiLog.push({ id, typ: ent.idTyp, felder: Object.keys(daten), ersetztAm: new Date().toISOString() });

  // Suchmuster fuer Freitext: nicht nur die Einzelwerte, sondern auch
  // zusammenhaengende Kombinationen in Feldreihenfolge. Sonst wird aus
  // "Anna Meier" ein "KUN-0001 KUN-0001" — was fuer das LLM wie zwei
  // Personen aussieht.
  const werte = Object.values(daten).map(String);
  const muster = [];
  for (let i = 0; i < werte.length; i++) {
    for (let j = i; j < werte.length; j++) {
      muster.push(werte.slice(i, j + 1).join(' '));
    }
  }
  // Laengste zuerst, damit "Anna Meier" vor "Anna" greift
  muster.sort((a, b) => b.length - a.length);

  for (const feld of freitextFelder) {
    if (typeof formular[feld] !== 'string') continue;
    let text = formular[feld];
    for (const m of muster) {
      const regex = m.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      text = text.replace(new RegExp(regex, 'gi'), () => id);
    }
    formular[feld] = text;
  }
}

// --- Muster-Erkennung im Freitext ------------------------------------------
// Faengt personenbezogene Daten ab, die der Kunde zusaetzlich in ein
// Freitextfeld getippt hat und die deshalb in keinem Formularfeld stehen.
//
// Bewusste Grenze: Hier werden nur Dinge erkannt, die ein festes MUSTER haben
// (Mail, Telefon, IBAN, Kartennummer). NAMEN im Freitext werden hier NICHT
// gefunden — dafuer braucht es eine Sprachmodell-basierte Erkennung
// (Presidio/spaCy, eigener Dienst). Das ist Issue #50.

const MUSTER = [
  {
    typ: 'email',
    praefix: 'MAIL',
    regex: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g,
  },
  {
    typ: 'iban',
    praefix: 'IBAN',
    // 2 Buchstaben Laendercode + 2 Pruefziffern + 11 bis 30 Zeichen
    regex: /\b[A-Z]{2}\d{2}[ ]?(?:[A-Z0-9]{4}[ ]?){2,7}[A-Z0-9]{1,4}\b/g,
  },
  {
    typ: 'kreditkarte',
    praefix: 'KART',
    // Trenner nur ZWISCHEN den Ziffern, sonst wird das Leerzeichen
    // dahinter mitverschluckt ("KART-0001verwenden")
    regex: /\b\d(?:[ -]?\d){12,18}\b/g,
    pruefe: luhnGueltig,       // ohne Pruefsumme zu viele Fehltreffer
  },
  {
    typ: 'telefon',
    praefix: 'TEL',
    // +49... oder 0... , 7 bis 14 weitere Ziffern, Trenner erlaubt
    regex: /(?:\+\d{1,3}[ /-]?|\b0)\d(?:[ /-]?\d){6,13}\b/g,
    pruefe: (t) => !/^\d{4}-\d{2}-\d{2}$/.test(t.trim()),   // keine Datumsangaben
  },
];

/** Luhn-Pruefsumme — trennt Kartennummern von Auftrags-/Bestellnummern. */
function luhnGueltig(text) {
  const ziffern = text.replace(/\D/g, '');
  if (ziffern.length < 13 || ziffern.length > 19) return false;
  let summe = 0, doppelt = false;
  for (let i = ziffern.length - 1; i >= 0; i--) {
    let z = Number(ziffern[i]);
    if (doppelt) { z *= 2; if (z > 9) z -= 9; }
    summe += z;
    doppelt = !doppelt;
  }
  return summe % 10 === 0;
}

for (const feld of freitextFelder) {
  if (typeof formular[feld] !== 'string') continue;
  for (const m of MUSTER) {
    formular[feld] = formular[feld].replace(m.regex, (treffer) => {
      // Bereits vergebene Kennung nicht erneut ersetzen
      if (/^[A-Z]{2,5}-\d{4}$/.test(treffer.trim())) return treffer;
      if (m.pruefe && !m.pruefe(treffer)) return treffer;

      zaehler[m.praefix] = (zaehler[m.praefix] ?? 0) + 1;
      const id = `${m.praefix}-${String(zaehler[m.praefix]).padStart(4, '0')}`;
      mapping[id] = { [m.typ]: treffer.trim() };
      piiLog.push({ id, typ: m.typ, quelle: `freitext:${feld}`, ersetztAm: new Date().toISOString() });
      return id;
    });
  }
}

// Kontrolle: steht in den Fachdaten noch Klartext?
const rest = JSON.stringify(formular);
const leckagen = klartextWerte.filter(w =>
  new RegExp(w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(rest)
);
if (leckagen.length) {
  throw new Error(
    'Pseudonymisierung unvollstaendig — Klartext noch in den Fachdaten. ' +
    'Betroffene Felder pruefen (Wert nicht im Log, um kein PII zu protokollieren). ' +
    `Anzahl: ${leckagen.length}`
  );
}

return [{
  json: {
    fachdaten: formular,   // -> geht weiter an LLM / Speicherung
    mapping,               // -> PII-Tresor, NICHT weiterreichen
    piiLog,                // -> Audit-Log (enthaelt bewusst keinen Klartext)
  }
}];

/**
 * Re-Identifizieren (lokal) — n8n Code-Node · VARIANTE A
 *
 * Setzt die IDs im LLM-Text wieder in Klartext zurueck. Gehoert zu Variante A:
 * das Sprachmodell formuliert die vollstaendige Nachricht und laesst die
 * Kennungen (KUN-0001) stehen; dieser Node ersetzt sie am Ende.
 *
 * Gegenstueck: Variante B (nachricht-aus-vorlage.js) — dort schreibt das LLM
 * nur den Sachtext, und die Anrede kommt aus einer Vorlage.
 * Vergleich beider Wege: siehe README.
 *
 * Voraussetzung dieser Variante: das Modell haelt sich an die Kennungen.
 * Tut es das nicht, entstehen erfundene IDs — deshalb die Pruefung unten.
 *
 * Eingabe (json):
 *   output        : string     Text des LLM, enthaelt Kennungen
 *   anzeigeFelder : string[]   optional: welche Felder den Anzeigenamen bilden
 *                              (Standard: alle Werte, durch Leerzeichen verbunden)
 * Ausgabe (json):
 *   nachricht     : Text mit Klarnamen
 *   erfundeneIds  : Kennungen, die das LLM erfunden hat (leer = gut)
 */

// Name des Nodes, der das Mapping haelt. Bei Umbenennung hier anpassen.
const PII_NODE = 'Pseudonymisieren (lokal)';

const eingabe = $input.first().json;
const entwurf = String(eingabe.output ?? eingabe.text ?? '');
const anzeigeFelder = eingabe.anzeigeFelder ?? null;

let mapping;
try {
  mapping = $(PII_NODE).first().json.mapping ?? {};
} catch (e) {
  throw new Error(`Mapping nicht gefunden — Node "${PII_NODE}" muss im selben Lauf existieren.`);
}

/** Baut aus den Feldern einer Person den Text, der im Schreiben stehen soll. */
function anzeigename(daten) {
  if (!daten || typeof daten !== 'object') return String(daten ?? '');
  const felder = anzeigeFelder ?? Object.keys(daten);
  return felder.map(f => daten[f]).filter(Boolean).join(' ');
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Laengste Kennung zuerst, damit KUN-0001 nicht durch eine Teilersetzung
// von KUN-000 beschaedigt wird. Ersetzung als Funktion, damit Dollarzeichen
// im Klartext nicht als Sondermuster gedeutet werden.
let nachricht = entwurf;
const ids = Object.keys(mapping).sort((a, b) => b.length - a.length);
for (const id of ids) {
  const klartext = anzeigename(mapping[id]);
  nachricht = nachricht.replace(new RegExp(escapeRegex(id), 'g'), () => klartext);
}

// Hat das Modell Kennungen erfunden, die es nie gesehen hat?
const bekannt = new Set(ids);
const erfunden = [...new Set(
  (entwurf.match(/\b[A-Z]{2,5}-\d{3,4}\b/g) ?? []).filter(t => !bekannt.has(t))
)];

return [{
  json: {
    nachricht,                  // -> menschliche Freigabe
    entwurfMitIds: entwurf,     // -> Audit-Log
    erfundeneIds: erfunden,
    warnung: erfunden.length
      ? `Das Modell hat ${erfunden.length} unbekannte Kennung(en) erzeugt: `
        + `${erfunden.join(', ')} — vor Freigabe pruefen.`
      : null,
  }
}];
